// «55» o «12,50»: enteros sin decimales, y con coma decimal (así se lee en Bolivia).
function cbMonto(n) {
  const c = Math.round(Number(n) * 100);
  if (!Number.isFinite(c)) return '';
  const a = Math.abs(c);
  const cen = a % 100;
  return (c < 0 ? '-' : '') + Math.floor(a / 100) + (cen ? ',' + (cen < 10 ? '0' : '') + cen : '');
