    if (con('closer')) b.push(rrBoton('b_closer', t('closer', 'Closer')));
    if (con('videos')) b.push(rrBoton('b_videos', t('videos', 'Videos')));
    if (con('pack')) b.push(rrBoton('b_pack', t('pack', 'Mejor el Pack')));
